def units(n):
    return [x for x in range(1, n) if math.gcd(x, n) == 1]
def order(x, n):
    k = 1
    v = x % n
    while v != 1:
        v = v * x % n
        k += 1
    return k
def cyclic(n):
    u = units(n)
    return any(order(x, n) == len(u) for x in u)
def cnt2(n):
    return sum(1 for x in units(n) if order(x, n) == 2)
def group_mod(n):
    for x in range(n):
        if not any(x * y % n == 1 for y in range(n)):
            return False
    return True
